<?php require_once __DIR__.'/_common.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']);if($title){$D['blogs'][]=['id'=>next_id($D['blogs']),'title'=>$title,'slug'=>slugify($_POST['slug']?:$title),'excerpt'=>trim($_POST['excerpt']),'content'=>$_POST['content'],'image'=>upload_image('image','blog'),'author'=>trim($_POST['author']?:'Janani Homeopathy'),'status'=>$_POST['status']==='published'?'published':'draft','created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')];save_db($D);header('Location: blogs.php');exit;}}ah('Add Blog');?><div class="panel"><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Slug</label><input name="slug"></div><div class="field full"><label>Excerpt</label><textarea name="excerpt"></textarea></div><div class="field full"><label>Content HTML</label><textarea name="content" required></textarea></div><div class="field"><label>Author</label><input name="author" value="Janani Homeopathy"></div><div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="published">Published</option></select></div><div class="field full"><input type="file" name="image" accept="image/*"></div><div class="field full"><button class="btn">Save Blog</button></div></form></div><?php af();
